// Interface language (ADR 0019). Every user-visible string in the frontend is written as `tr('繁體中文原文')`:
// the Traditional Chinese source text is the key, so the source language needs no catalog and a missing entry
// falls back to the readable original. Other languages are catalogs keyed by that source text
// (`src/lib/i18n/<language>.json`, generated by `scripts/i18n-catalog.mjs` from the `tr()` calls plus hand-written
// overrides). Placeholders are `{0}`, `{1}`… filled from an array (or `{name}` from an object).
//
// The language is fixed when the page loads: changing it saves the choice and reloads the window, so module-level
// constants and plain functions can call `tr()` without any reactivity.

import zhCN from './i18n/zh-CN.json' with { type: 'json' };

/** Languages with an interface. `zh-TW` is the source language and has no catalog. */
export const LANGUAGES = Object.freeze(['zh-TW', 'zh-CN']);
export const SOURCE_LANGUAGE = 'zh-TW';
/** What the settings choice may be: follow the system, or one of the languages. */
export const LANGUAGE_CHOICES = Object.freeze(['system', ...LANGUAGES]);
export const LANGUAGE_STORAGE_KEY = 'moe.languageChoice';

/** @type {Record<string, Record<string, string>>} */
const CATALOGS = { 'zh-CN': zhCN };

/** @param {unknown} value @returns {'system' | 'zh-TW' | 'zh-CN'} */
export function normalizeLanguageChoice(value) {
  return LANGUAGE_CHOICES.includes(/** @type {string} */ (value)) ? /** @type {'system'|'zh-TW'|'zh-CN'} */ (value) : 'system';
}

/**
 * The interface language for a list of BCP 47 tags (navigator.languages): Simplified for zh-CN, zh-SG and zh-Hans,
 * Traditional for everything else (the source language, until more languages exist).
 * @param {readonly string[] | undefined} tags
 * @returns {'zh-TW' | 'zh-CN'}
 */
export function resolveSystemLanguage(tags) {
  for (const raw of tags ?? []) {
    const tag = String(raw).toLowerCase();
    if (tag.startsWith('zh')) {
      return /^zh(-hans|-cn|-sg|$)/.test(tag) && !/-(tw|hk|mo|hant)/.test(tag) ? 'zh-CN' : 'zh-TW';
    }
  }
  return 'zh-TW';
}

/** @param {'system' | 'zh-TW' | 'zh-CN'} choice @param {readonly string[] | undefined} [systemTags] @returns {'zh-TW' | 'zh-CN'} */
export function resolveLanguage(choice, systemTags) {
  if (choice === 'zh-TW' || choice === 'zh-CN') return choice;
  return resolveSystemLanguage(systemTags);
}

/** The choice remembered by this window's storage (the settings file is the authority; this copy lets the first paint use the right language). */
export function readStoredLanguageChoice() {
  try {
    return normalizeLanguageChoice(globalThis.localStorage?.getItem(LANGUAGE_STORAGE_KEY));
  } catch {
    return 'system';
  }
}

/** @param {'system' | 'zh-TW' | 'zh-CN'} choice */
export function storeLanguageChoice(choice) {
  try {
    globalThis.localStorage?.setItem(LANGUAGE_STORAGE_KEY, choice);
  } catch {
    // Storage may be unavailable; the settings file still keeps the choice.
  }
}

let choice = readStoredLanguageChoice();
let active = resolveLanguage(choice, globalThis.navigator?.languages ?? (globalThis.navigator?.language ? [globalThis.navigator.language] : undefined));
if (globalThis.document?.documentElement) {
  globalThis.document.documentElement.lang = active === 'zh-CN' ? 'zh-Hans' : 'zh-Hant';
}

export function getLanguageChoice() {
  return choice;
}

export function getActiveLanguage() {
  return active;
}

/**
 * Pick the interface language for tests and tools (the app itself only changes it by reloading).
 * @param {'system' | 'zh-TW' | 'zh-CN'} next @param {readonly string[]} [systemTags]
 */
export function setLanguageForTesting(next, systemTags) {
  choice = next;
  active = resolveLanguage(next, systemTags);
}

/** @param {string} template @param {readonly unknown[] | Record<string, unknown> | undefined} params */
export function formatMessage(template, params) {
  if (params === undefined || params === null) return template;
  return template.replace(/\{(\w+)\}/g, (whole, name) => {
    const value = Array.isArray(params) ? params[Number(name)] : /** @type {Record<string, unknown>} */ (params)[name];
    return value === undefined ? whole : String(value);
  });
}

/**
 * Translate a Traditional Chinese source string. `tr('共 {0} 首', [count])`.
 * @param {string} source @param {readonly unknown[] | Record<string, unknown>} [params]
 */
export function tr(source, params) {
  const catalog = CATALOGS[active];
  const text = catalog && Object.hasOwn(catalog, source) ? catalog[source] : source;
  return formatMessage(text, params);
}
